SELECT c.thread_id,c.agent_id,d.retention_days,c.storage,a.paused,c.retirement_epoch FROM sidecar_conversations c JOIN agent_deployments d ON d.agent_id=c.agent_id JOIN agents a ON a.id=c.agent_id WHERE c.storage IN ('corrosion','retiring') AND (EXTRACT(EPOCH FROM NOW()-c.last_activity_at)>=d.retention_days*86400 OR c.storage='retiring' OR a.paused) AND NOT EXISTS(SELECT 1 FROM chat_invocations i WHERE i.thread_id=c.thread_id AND i.agent_id=c.agent_id AND i.status IN ('pending','running')) ORDER BY c.last_activity_at LIMIT 50;
